import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:path/path.dart' as p;
import 'package:sqflite_sqlcipher/sqflite.dart';
class LocalDatabase{LocalDatabase._();static final instance=LocalDatabase._();final _secure=const FlutterSecureStorage();Database? _db;Future<Database> get database async{if(_db!=null)return _db!;final key=await _secure.read(key:'finaro.db.key')??await _newKey();final path=p.join(await getDatabasesPath(),'finaro_secure.db');_db=await openDatabase(path,password:key,version:2,onCreate:_create,onUpgrade:_upgrade);return _db!;}Future<String> _newKey()async{final k='${DateTime.now().microsecondsSinceEpoch.toRadixString(16)}${DateTime.now().millisecondsSinceEpoch.toRadixString(16)}';await _secure.write(key:'finaro.db.key',value:k);return k;}Future<void> _create(Database db,int v)async{await db.execute('CREATE TABLE profile(id TEXT PRIMARY KEY,name TEXT NOT NULL,opening_balance_rials INTEGER NOT NULL,opening_balance_date TEXT)');await db.execute('CREATE TABLE income(id TEXT PRIMARY KEY,title TEXT NOT NULL,amount_rials INTEGER NOT NULL,frequency TEXT NOT NULL,start_date TEXT NOT NULL,pay_day INTEGER)');await db.execute('CREATE TABLE expense(id TEXT PRIMARY KEY,title TEXT NOT NULL,amount_rials INTEGER NOT NULL,frequency TEXT NOT NULL,category TEXT NOT NULL,date TEXT NOT NULL,start_date TEXT,payment_day INTEGER)');await db.execute('CREATE TABLE liability(id TEXT PRIMARY KEY,title TEXT NOT NULL,type TEXT NOT NULL,total_rials INTEGER NOT NULL,installment_rials INTEGER NOT NULL,remaining_installments INTEGER NOT NULL,frequency TEXT NOT NULL,payment_date TEXT NOT NULL,payment_day INTEGER)');await db.execute('CREATE TABLE category(id TEXT PRIMARY KEY,title TEXT UNIQUE NOT NULL)');await db.insert('profile',{'id':'local-profile','name':'','opening_balance_rials':0,'opening_balance_date':null});for(final c in ['خوراک','حمل‌ونقل','مسکن','سلامت','خرید','تفریح','قبوض'])await db.insert('category',{'id':c.hashCode.toString(),'title':c});} Future<void> _upgrade(Database db,int oldVersion,int newVersion) async { if(oldVersion < 2) { await db.execute('ALTER TABLE profile ADD COLUMN opening_balance_date TEXT'); } } }
